import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, time, id)
    sell_heap = []  # (price, time, id)
    book = {}  # id -> dict with side, price, qty, time, active
    time_counter = 0

    def add_to_book(order_id):
        o = book[order_id]
        if o['side'] == 'buy':
            heapq.heappush(buy_heap, (-o['price'], o['time'], order_id))
        else:
            heapq.heappush(sell_heap, (o['price'], o['time'], order_id))

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        time_counter += 1

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0 and heap:
            if side == 'buy':
                top_price, top_time, top_id = heap[0]
            else:
                neg_price, top_time, top_id = heap[0]
                top_price = -neg_price

            if top_id not in book or not book[top_id]['active'] or book[top_id]['qty'] <= 0:
                heapq.heappop(heap)
                continue

            if typ == 'market':
                match_ok = True
            else:
                if side == 'buy':
                    match_ok = top_price <= price
                else:
                    match_ok = top_price >= price

            if not match_ok:
                break

            resting = book[top_id]
            trade_qty = min(remaining, resting['qty'])

            if side == 'buy':
                trades.append([oid, top_id, top_price, trade_qty])
            else:
                trades.append([top_id, oid, top_price, trade_qty])

            remaining -= trade_qty
            resting['qty'] -= trade_qty

            if resting['qty'] == 0:
                resting['active'] = False
                heapq.heappop(heap)

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'time': time_counter, 'active': True}
            add_to_book(oid)
        # ioc and market discard any remaining quantity

    return trades

